INSERT OR REPLACE INTO pages (id, slug, title, description, status, content, author_id, published_at, created_at, updated_at) VALUES ('page-home', 'home', 'หน้าแรก - โรงเรียนวัดบางน้ำวน (รอดพิทยาคม)', 'เว็บไซต์ทางการ โรงเรียนวัดบางน้ำวน (รอดพิทยาคม) สำนักงานเขตพื้นที่การศึกษาประถมศึกษาสมุทรสาคร', 'published', '[{"id":"blk-hero","type":"hero_banner","data":{"badge":"ยินดีต้อนรับสู่สถานศึกษาแห่งการเรียนรู้","title":"โรงเรียนวัดบางน้ำวน\n(รอดพิทยาคม)","subtitle":"มุ่งมั่นจัดการศึกษาอย่างมีคุณภาพ ปลูกฝังคุณธรรม นำความรู้ สู่ชุมชนที่ยั่งยืน สังกัด สพป.สมุทรสาคร","primaryButtonText":"ข่าวประชาสัมพันธ์","primaryButtonUrl":"/news","secondaryButtonText":"ข้อมูลโรงเรียน","secondaryButtonUrl":"/about/history","backgroundImageUrl":""}},{"id":"blk-announcements","type":"announcement_list","data":{"title":"ประกาศด่วนและข่าวสำคัญ","limit":3,"showBadge":true}},{"id":"blk-text-intro","type":"text_section","data":{"title":"วิสัยทัศน์สถานศึกษา (Vision)","content":"โรงเรียนวัดบางน้ำวน (รอดพิทยาคม) มุ่งเน้นการจัดการศึกษาอย่างรอบด้าน เพื่อพัฒนาผู้เรียนให้มีความรู้คู่คุณธรรม มีทักษะการเรียนรู้ในศตวรรษที่ 21 อนุรักษ์ทรัพยากรธรรมชาติและสิ่งแวดล้อมท้องถิ่น และพร้อมก้าวสู่สังคมแห่งอนาคตอย่างมั่นคงและมีความสุข","alignment":"center"}},{"id":"blk-news","type":"news_list","data":{"title":"ข่าวประชาสัมพันธ์ล่าสุด","subtitle":"ติดตามกิจกรรม การเรียนรู้ และความเคลื่อนไหวภายในโรงเรียน","limit":3,"showCategoryBadge":true}},{"id":"blk-events","type":"event_list","data":{"title":"ปฏิทินกิจกรรมโรงเรียน","limit":2}},{"id":"blk-botanical","type":"botanical_highlight","data":{"title":"สวนพฤกษศาสตร์โรงเรียน","subtitle":"แหล่งเรียนรู้ธรรมชาติ ภูมิปัญญาพันธุ์ไม้ท้องถิ่นรอดพิทยาคม","limit":3}},{"id":"blk-eservices","type":"eservice_links","data":{"title":"ระบบบริการออนไลน์ (E-Service)","subtitle":"เข้าถึงบริการทางการศึกษาได้อย่างสะดวกรวดเร็ว ทุกที่ทุกเวลา"}},{"id":"blk-staff","type":"staff_cards","data":{"title":"คณะผู้บริหารและบุคลากร","department":"all","limit":3}},{"id":"blk-cta","type":"cta","data":{"title":"ร่วมเป็นส่วนหนึ่งของครอบครัวรอดพิทยาคม","description":"เปิดรับสมัครนักเรียนใหม่ทุกระดับชั้น พร้อมให้คำปรึกษาด้านการศึกษา","buttonText":"ติดต่อสอบถามเพิ่มเติม","buttonUrl":"/contact"}}]', 'usr-superadmin-01', '2026-10-20T10:10:18.972Z', '2026-10-20T10:10:18.972Z', '2026-10-20T10:10:18.972Z');
INSERT OR REPLACE INTO news (id, slug, title, summary, content, category, cover_image_url, status, author_id, view_count, published_at, created_at, updated_at) VALUES ('news-01', 'wai-kru-ceremony-2569', 'พิธีไหว้ครู ประจำปีการศึกษา 2569 น้อมจิตวันทา บูชาพระคุณครู', 'โรงเรียนวัดบางน้ำวน (รอดพิทยาคม) จัดกิจกรรมพิธีไหว้ครู เพื่อให้นักเรียนได้แสดงความกตัญญูกตเวทิตาต่อครูอาจารย์', 'โรงเรียนวัดบางน้ำวน (รอดพิทยาคม) ได้จัดพิธีไหว้ครู ประจำปีการศึกษา 2569 เพื่อให้นักเรียนทุกระดับชั้นได้ร่วมแสดงความกตัญญูกตเวทิตาต่อคุณครูผู้ประสิทธิ์ประสาทวิชาความรู้ กิจกรรมประกอบด้วยพิธีทำบุญตักบาตร การประกวดพานไหว้ครูประเภทสวยงามและประเภทความคิดสร้างสรรค์ บรรยากาศเป็นไปด้วยความอบอุ่นและเปี่ยมด้วยความหมาย', 'activity', NULL, 'published', NULL, 142, '2026-10-20T10:10:18.939Z', '2026-10-20T10:10:18.939Z', '2026-10-20T10:10:18.939Z');
INSERT OR REPLACE INTO news (id, slug, title, summary, content, category, cover_image_url, status, author_id, view_count, published_at, created_at, updated_at) VALUES ('news-02', 'science-week-exhibition-2569', 'สัปดาห์วิทยาศาสตร์และเทคโนโลยี ส่งเสริมนวัตกรรมเยาวชนคนรุ่นใหม่', 'กลุ่มสาระการเรียนรู้วิทยาศาสตร์และเทคโนโลยี จัดนิทรรศการและการแข่งขันโครงงานสิ่งประดิษฐ์เพื่อการอนุรักษ์สิ่งแวดล้อม', 'กลุ่มสาระการเรียนรู้วิทยาศาสตร์และเทคโนโลยี โรงเรียนวัดบางน้ำวน (รอดพิทยาคม) จัดงานสัปดาห์วิทยาศาสตร์ขึ้น ภายในงานมีการจัดแสดงนิทรรศการโครงงานทางวิทยาศาสตร์ โครงงานสำรวจระบบนิเวศป่าชายเลนและสายน้ำบางน้ำวน การแข่งขันจรวดขวดน้ำ และการตอบปัญหาวิทยาศาสตร์ เพื่อกระตุ้นกระบวนการคิดแบบสะเต็มศึกษา (STEM Education) ให้แก่นักเรียน', 'academic', NULL, 'published', NULL, 98, '2026-10-20T10:10:18.939Z', '2026-10-20T10:10:18.939Z', '2026-10-20T10:10:18.939Z');
INSERT OR REPLACE INTO news (id, slug, title, summary, content, category, cover_image_url, status, author_id, view_count, published_at, created_at, updated_at) VALUES ('news-03', 'academic-award-samut-sakhon-2569', 'นักเรียนโรงเรียนวัดบางน้ำวน คว้ารางวัลเหรียญทอง การแข่งขันความเป็นเลิศทางวิชาการ', 'ขอแสดงความยินดีกับตัวแทนนักเรียนที่ได้รับรางวัลจากการแข่งขันระดับเขตพื้นที่การศึกษาประถมศึกษาสมุทรสาคร', 'ขอแสดงความชื่นชมและยินดีกับนักเรียนตัวแทนโรงเรียนวัดบางน้ำวน (รอดพิทยาคม) ที่ได้รับรางวัลเหรียญทอง อันดับ 1 ในการแข่งขันตอบปัญหาสุขศึกษาและวิทยาศาสตร์สิ่งแวดล้อม งานมหกรรมวิชาการระดับเขตพื้นที่การศึกษาประถมศึกษาสมุทรสาคร สร้างความภาคภูมิใจให้แก่คณะครูและชาวบางน้ำวนเป็นอย่างยิ่ง', 'award', NULL, 'published', NULL, 215, '2026-10-20T10:10:18.939Z', '2026-10-20T10:10:18.939Z', '2026-10-20T10:10:18.939Z');
INSERT OR REPLACE INTO announcements (id, slug, title, content, type, is_pinned, attachment_url, status, author_id, published_at, created_at, updated_at) VALUES ('ann-01', 'admission-announcement-2569', 'ประกาศรับสมัครนักเรียนใหม่ ปีการศึกษา 2569 ระดับชั้นอนุบาลและประถมศึกษา', 'โรงเรียนวัดบางน้ำวน (รอดพิทยาคม) เปิดรับสมัครนักเรียนใหม่ ประจำปีการศึกษา 2569 โดยผู้ปกครองสามารถยื่นเอกสารการสมัครได้ที่ห้องธุรการโรงเรียนในวันและเวลาราชการ หรือสมัครผ่านระบบ E-Service ทางเว็บไซต์ของโรงเรียน', 'admission', 1, NULL, 'published', NULL, '2026-10-20T10:10:18.945Z', '2026-10-20T10:10:18.945Z', '2026-10-20T10:10:18.945Z');
INSERT OR REPLACE INTO announcements (id, slug, title, content, type, is_pinned, attachment_url, status, author_id, published_at, created_at, updated_at) VALUES ('ann-02', 'parent-meeting-term-1-2569', 'กำหนดการประชุมผู้ปกครองภาคเรียนที่ 1 ประจำปีการศึกษา 2569', 'ขอเชิญผู้ปกครองนักเรียนทุกระดับชั้นเข้าร่วมการประชุมผู้ปกครอง เพื่อรับฟังแนวทางการจัดการเรียนรู้และรับผลการพัฒนาการเรียนรู้ของนักเรียน ณ หอประชุมโรงเรียนวัดบางน้ำวน (รอดพิทยาคม)', 'general', 0, NULL, 'published', NULL, '2026-10-20T10:10:18.945Z', '2026-10-20T10:10:18.945Z', '2026-10-20T10:10:18.945Z');
INSERT OR REPLACE INTO events (id, title, description, start_date, end_date, location, cover_image_url, status, author_id, created_at, updated_at) VALUES ('evt-01', 'กิจกรรมเปิดบ้านวิชาการ Open House 2569', 'เปิดโอกาสให้นักเรียนและผู้ปกครองเข้าชมนิทรรศการผลงานและการจัดการเรียนการสอนของโรงเรียน', '2026-11-15T08:30:00Z', '2026-11-15T15:30:00Z', 'อาคารเรียนและหอประชุม โรงเรียนวัดบางน้ำวน (รอดพิทยาคม)', NULL, 'published', NULL, '2026-10-20T10:10:18.948Z', '2026-10-20T10:10:18.948Z');
INSERT OR REPLACE INTO events (id, title, description, start_date, end_date, location, cover_image_url, status, author_id, created_at, updated_at) VALUES ('evt-02', 'การแข่งขันกีฬาสีภายใน รอดพิทยาคมเกมส์', 'ส่งเสริมสุขภาพ พลานามัย ความมีน้ำใจนักกีฬา และความสามัคคีในหมู่คณะ', '2026-12-18T08:00:00Z', '2026-12-19T16:00:00Z', 'สนามกีฬาโรงเรียนวัดบางน้ำวน', NULL, 'published', NULL, '2026-10-20T10:10:18.948Z', '2026-10-20T10:10:18.948Z');
