INSERT OR REPLACE INTO staff (id, name, position, department, order_index, image_url, qualification, email, is_active, created_at, updated_at) VALUES ('stf-03', 'ครูหัวหน้าฝ่ายกิจการนักเรียน (ข้อมูลตัวอย่าง)', 'ครูชำนาญการ', 'student_affairs', 3, NULL, 'ศษ.บ. พลศึกษา', 'student_affairs@bnw.ac.th', 1, '2026-10-20T10:10:18.952Z', '2026-10-20T10:10:18.952Z');
INSERT OR REPLACE INTO botanical_plants (id, thai_name, common_name, scientific_name, family, characteristics, location_in_school, educational_value, image_url, verification_status, qr_code, created_at, updated_at) VALUES ('plant-01', 'ราชพฤกษ์ (คูน)', 'Golden Shower', 'Cassia fistula L.', 'Fabaceae (Leguminosae - Caesalpinioideae)', 'ไม้ยืนต้นขนาดกลาง ผลัดใบ สูงประมาณ 10-15 เมตร ดอกออกเป็นช่อห้อยระย้าสีเหลืองอร่าม ผลเป็นฝักยาวทรงกระบอกสีน้ำตาลเข้มเกือบดำ เมล็ดแบนรูปไข่', 'บริเวณสวนหย่อมด้านหน้าเสาธงและอาคาร 1', 'ดอกเป็นดอกไม้ประจำชาติไทย ฝักแก่ใช้เป็นยาระบายและสมุนไพรขับเสมหะ เปลือกต้นมีสารแทนนินใช้ฟอกหนัง', NULL, 'verified', NULL, '2026-10-20T10:10:18.956Z', '2026-10-20T10:10:18.956Z');
INSERT OR REPLACE INTO botanical_plants (id, thai_name, common_name, scientific_name, family, characteristics, location_in_school, educational_value, image_url, verification_status, qr_code, created_at, updated_at) VALUES ('plant-02', 'ทองกวาว (จาน)', 'Flame of the Forest', 'Butea monosperma (Lam.) Taub.', 'Fabaceae', 'ไม้ยืนต้นขนาดกลาง ลำต้นมักคดงอ ดอกสีส้มแสดหรือแดงคล้ายเปลวเพลิง ออกเป็นช่อยาวตามกิ่งก้าน ใบประกอบแบบขนนกมี 3 ใบย่อย', 'แปลงพฤกษศาสตร์ข้างสนามกีฬาโรงเรียน', 'ดอกนำมาต้มย้อมผ้าให้สีส้ม ยางจากลำต้นใช้เป็นยาสมานแผล และเป็นพืชศึกษาการปรับตัวในฤดูแล้ง', NULL, 'verified', NULL, '2026-10-20T10:10:18.956Z', '2026-10-20T10:10:18.956Z');
INSERT OR REPLACE INTO botanical_plants (id, thai_name, common_name, scientific_name, family, characteristics, location_in_school, educational_value, image_url, verification_status, qr_code, created_at, updated_at) VALUES ('plant-03', 'ลีลาวดี (ลั่นทมขาว)', 'White Frangipani', 'Plumeria obtusa L.', 'Apocynaceae', 'ไม้พุ่มหรือไม้ยืนต้นขนาดเล็ก กิ่งก้านอวบน้ำ มียางสีขาว ใบหนารูปไข่กลับ ดอกสีขาวใจกลางสีเหลือง มีกลิ่นหอมละมุน', 'บริเวณทางเดินเชื่อมระหว่างอาคารเรียน 1 และ 2', 'ศึกษาโครงสร้างดอกพืชวงศ์ Apocynaceae การปรับตัวของพืชอวบน้ำ และคุณสมบัติของน้ำมันหอมระเหย', NULL, 'verified', NULL, '2026-10-20T10:10:18.956Z', '2026-10-20T10:10:18.956Z');
INSERT OR REPLACE INTO academic_courses (id, level, title, description, learning_areas, order_index, created_at, updated_at) VALUES ('crs-01', 'primary', 'หลักสูตรแกนกลางการศึกษาขั้นพื้นฐาน ระดับชั้นประถมศึกษา (ป.1 - ป.6)', 'มุ่งเน้นการเสริมสร้างทักษะพื้นฐานด้านการอ่าน การเขียน การคิดคำนวณ ปลูกฝังคุณธรรม จริยธรรม และกระบวนการคิดตามช่วงวัย', '[{"subject":"ภาษาไทย","credits":"5 ชั่วโมง/สัปดาห์"},{"subject":"คณิตศาสตร์","credits":"5 ชั่วโมง/สัปดาห์"},{"subject":"วิทยาศาสตร์และเทคโนโลยี","credits":"3 ชั่วโมง/สัปดาห์"},{"subject":"ภาษาอังกฤษ","credits":"3 ชั่วโมง/สัปดาห์"},{"subject":"สังคมศึกษา ศาสนา และวัฒนธรรม","credits":"2 ชั่วโมง/สัปดาห์"}]', 1, '2026-10-20T10:10:18.969Z', '2026-10-20T10:10:18.969Z');
INSERT OR REPLACE INTO academic_courses (id, level, title, description, learning_areas, order_index, created_at, updated_at) VALUES ('crs-02', 'lower_secondary', 'หลักสูตรระดับชั้นมัธยมศึกษาตอนต้น (ม.1 - ม.3)', 'มุ่งเน้นการสำรวจความถนัด พัฒนาทักษะการเรียนรู้ขั้นสูง การประยุกต์ใช้เทคโนโลยี และเตรียมความพร้อมสู่สายอาชีพหรือสายสามัญ', '[{"subject":"ภาษาไทยพื้นฐาน","credits":"3 คาบ/สัปดาห์"},{"subject":"คณิตศาสตร์เชิงคิดวิเคราะห์","credits":"3 คาบ/สัปดาห์"},{"subject":"วิทยาศาสตร์และสะเต็มศึกษา","credits":"3 คาบ/สัปดาห์"},{"subject":"ภาษาอังกฤษเพื่อการสื่อสาร","credits":"3 คาบ/สัปดาห์"}]', 2, '2026-10-20T10:10:18.969Z', '2026-10-20T10:10:18.969Z');
